const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const job_id = (body.job_id || '').toString();
const platforms = (Array.isArray(body.platforms) && body.platforms.length) ? body.platforms : ['linkedin', 'x', 'instagram'];
const content_type = (body.content_type || 'static').toString();
return [{ json: { job_id, platforms, content_type } }];

const job = $('Get Job').first().json;
const ct = $('Parse Webhook Input').first().json.content_type || 'static';
const platforms = $('Parse Webhook Input').first().json.platforms || ['linkedin', 'x', 'instagram'];

// Prefer DB-stored shortlink, fall back to fresh TinyURL result.
let shortLink = (job.shortlink || '').trim();
if (!shortLink) {
  try {
    const td = ($('Shorten URL').first().json.data || '').trim();
    if (td.startsWith('http')) shortLink = td;
  } catch (e) {}
}

const SYSTEM = {
  linkedin: 'You write LinkedIn copy for Project Digital. 1300-1900 characters. First 2 lines are the hook. Short paragraphs, generous line breaks. 3-5 hashtags at end. Professional but human, 0-3 emoji. CTA is mandatory: LinkedIn suppresses reach for outbound links in the post body — do NOT paste the URL in the body. End the body with the exact line: Full breakdown → first comment ↓. Return the short link as first_comment_link in the JSON. Return ONLY a JSON object, no code fences: { "platform": "linkedin", "is_article": false, "hook": "", "body": "", "hashtags": [], "char_count": 0, "first_comment_link": "" }',
  x: 'You write X (Twitter) copy for Project Digital. CTA mandatory: always end the single post with the short link. Single post must be ≤280 chars including the link. Also give a 3-5 tweet thread: tweet 1 is a hook with an open loop, the last tweet has the CTA and the short link. Sharp, confident, 0-2 hashtags. Return ONLY a JSON object, no code fences: { "platform": "x", "single_post": "", "thread": [], "hashtags": [], "link": "" }',
  instagram: 'You write Instagram captions for Project Digital. 125-600 visible characters, hook in the first line, warm and conversational, purposeful emoji. CTA mandatory: include the line "Full read → link in bio 🔗" near the end — Instagram has no clickable in-caption links. End with one engagement prompt. 8-15 hashtags (broad and niche). Return the short link as link_in_bio in the JSON. Return ONLY a JSON object, no code fences: { "platform": "instagram", "content_type": "static", "caption": "", "engagement_prompt": "", "hashtags": [], "link_in_bio": "", "carousel_slides": [], "reel_onscreen_hook": "" }',
  facebook: 'You write Facebook copy for Project Digital. 400-600 characters, conversational relatable opener. CTA mandatory: end the post with the short link on its own line. 0-2 emoji, 0-3 hashtags. Return ONLY a JSON object, no code fences: { "platform": "facebook", "body": "", "link": "", "engagement_prompt": "", "hashtags": [] }',
  threads: 'You write Threads copy for Project Digital. ≤500 characters, conversational, invites replies. CTA mandatory: end with the short link on its own line. 0-1 hashtags. Return ONLY a JSON object, no code fences: { "platform": "threads", "post": "", "continuation": [], "link": "" }',
  pinterest: 'You write Pinterest Pin copy for Project Digital. Pin title ≤100 chars, keyword-forward, benefit-driven. Pin description 150-500 chars with natural keywords, ending with "Read the full guide →" followed by the short link. 3-6 hashtags. Set the short link as destination_url. Return ONLY a JSON object, no code fences: { "platform": "pinterest", "pin_title": "", "pin_description": "", "destination_url": "", "hashtags": [] }',
  tiktok: 'You write TikTok copy for Project Digital. Caption ≤150 characters, punchy lowercase-casual. CTA mandatory: end caption with "full guide → link in bio". On-screen hook ≤8 words. Provide 3-5 beat script outline. Return the short link as link_in_bio. Return ONLY a JSON object, no code fences: { "platform": "tiktok", "onscreen_hook": "", "caption": "", "hashtags": [], "script_beats": [], "sound_style": "", "link_in_bio": "" }'
};

const user = 'Topic: ' + (job.topic || '') + '\nAngle: ' + (job.chosen_angle || '') + '\nContent type: ' + ct + '\nShort link: ' + shortLink + '\n\nBlog draft:\n' + (job.draft_md || '');

return platforms.map(function(p) { return { json: { platform: p, system: SYSTEM[p] || SYSTEM.instagram, user: user } }; });

const tasks = $('Build Caption Tasks').all();
const job_id = $('Get Job').first().json.id;
return $input.all().map(function(item, i) {
  const res = item.json;
  const raw = (res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '';
  let txt = raw.trim();
  if (txt.startsWith('```')) {
    txt = txt.substring(txt.indexOf('\n') + 1);
    if (txt.endsWith('```')) txt = txt.slice(0, -3);
    txt = txt.trim();
  }
  let captionJson;
  try { captionJson = JSON.parse(txt); } catch (e) { captionJson = { parse_error: e.message, raw: raw }; }
  const platform = tasks[i] ? tasks[i].json.platform : (captionJson.platform || 'unknown');
  return { json: { job_id: job_id, platform: platform, captionJson: captionJson } };
});

const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const notes = (body.notes || body.feedback || '').toString();
const job_id = $('Get Job').first().json.id;
return [{ json: { job_id: job_id, notes: notes } }];
